import { createHash } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { runLogin } from "./login.js";
const { closeLoginWindow, openBrowser, saveCredentials, getConfig, hasCredentials, delay, } = vi.hoisted(() => ({
    delay: vi.fn(async (_ms) => { }),
    openBrowser: vi.fn(() => ({
        launched: true,
    })),
    closeLoginWindow: vi.fn(async () => { }),
    saveCredentials: vi.fn(),
    getConfig: vi.fn(() => ({
        serviceUrl: "https://test.invalid",
        apiKey: null,
    })),
    hasCredentials: vi.fn(() => false),
}));
vi.mock("../config.js", () => ({
    saveCredentials,
    getConfig,
    hasCredentials,
    formatNonProductionEndpointSuffix: () => "",
}));
vi.mock("../browser.js", () => ({ closeLoginWindow, openBrowser }));
vi.mock("../analytics.js", () => ({ reportHandoff: vi.fn() }));
vi.mock("node:timers/promises", () => ({ setTimeout: delay }));
const platform = { authPath: "codex" };
beforeEach(() => {
    vi.clearAllMocks();
    delay.mockImplementation(async () => { });
    openBrowser.mockReturnValue({ launched: true });
    hasCredentials.mockReturnValue(false);
    getConfig.mockReturnValue({
        serviceUrl: "https://test.invalid",
        apiKey: null,
    });
    vi.spyOn(console, "log").mockImplementation(() => { });
});
afterEach(() => vi.restoreAllMocks());
describe("plugin window login", () => {
    it("opens the plugin sign-in window, claims a PKCE ticket, and saves the key", async () => {
        const fetch = vi
            .spyOn(globalThis, "fetch")
            .mockResolvedValueOnce(Response.json({ id: "ticket-1", pollIntervalMs: 1 }))
            .mockResolvedValueOnce(Response.json({ status: "completed", data: { token: "secret-key" } }))
            .mockResolvedValueOnce(Response.json({
            user: { email: "user@example.com" },
            organization: { id: "org-1" },
        }));
        await runLogin(platform, "test", { exitOnComplete: false });
        const created = JSON.parse(String(fetch.mock.calls[0][1]?.body));
        const polled = new URL(String(fetch.mock.calls[1][0]));
        const verifier = polled.searchParams.get("verifier");
        expect(created).toMatchObject({ kind: "auth.login", pkceMethod: "S256" });
        expect(created.pkceChallenge).toBe(createHash("sha256")
            .update(verifier ?? "")
            .digest("base64url"));
        const signInUrl = openBrowser.mock.calls[0][0];
        const parsedSignInUrl = new URL(signInUrl);
        expect(parsedSignInUrl.origin + parsedSignInUrl.pathname).toBe("https://test.invalid/plugin/auth/codex");
        expect(parsedSignInUrl.searchParams.get("ticket")).toBe("ticket-1");
        expect(parsedSignInUrl.searchParams.get("loginWindow")).toMatch(/^[a-f0-9]{32}$/);
        expect(console.log).toHaveBeenCalledWith(`Sign in to Bitfab: ${signInUrl}`);
        expect(closeLoginWindow).toHaveBeenCalledWith(signInUrl);
        expect(saveCredentials.mock.invocationCallOrder[0]).toBeLessThan(closeLoginWindow.mock.invocationCallOrder[0]);
        expect(saveCredentials).toHaveBeenCalledWith("secret-key");
        const logs = vi.mocked(console.log).mock.calls.flat().join(" ");
        expect(logs).not.toContain("secret-key");
        expect(logs).not.toContain(verifier);
    });
    it("does not issue a ticket for valid saved credentials", async () => {
        hasCredentials.mockReturnValue(true);
        getConfig.mockReturnValue({
            serviceUrl: "https://test.invalid",
            apiKey: "existing-key",
        });
        const fetch = vi
            .spyOn(globalThis, "fetch")
            .mockResolvedValue(Response.json({ user: { email: "user@example.com" } }));
        await runLogin(platform, "test");
        expect(fetch).toHaveBeenCalledTimes(1);
        expect(openBrowser).not.toHaveBeenCalled();
        expect(saveCredentials).not.toHaveBeenCalled();
        expect(closeLoginWindow).not.toHaveBeenCalled();
    });
    it("fails expired tickets without persisting credentials", async () => {
        vi.spyOn(globalThis, "fetch")
            .mockResolvedValueOnce(Response.json({ id: "ticket-1" }))
            .mockResolvedValueOnce(Response.json({ status: "expired" }));
        await expect(runLogin(platform, "test")).rejects.toThrow("Login expired");
        expect(saveCredentials).not.toHaveBeenCalled();
        expect(closeLoginWindow).not.toHaveBeenCalled();
    });
    it.each([
        429, 500, 503,
    ])("recovers from HTTP %i while waiting for login", async (status) => {
        const fetch = vi
            .spyOn(globalThis, "fetch")
            .mockResolvedValueOnce(Response.json({ id: "ticket-1" }))
            .mockResolvedValueOnce(new Response(null, { status }))
            .mockResolvedValueOnce(Response.json({ status: "completed", data: { token: "secret-key" } }))
            .mockResolvedValueOnce(Response.json({ user: { email: "user@example.com" } }));
        delay.mockImplementationOnce(async () => {
            expect(saveCredentials).not.toHaveBeenCalled();
            expect(closeLoginWindow).not.toHaveBeenCalled();
        });
        await runLogin(platform, "test");
        expect(fetch).toHaveBeenCalledTimes(4);
        expect(delay).toHaveBeenCalledExactlyOnceWith(1500);
        expect(saveCredentials).toHaveBeenCalledExactlyOnceWith("secret-key");
        expect(closeLoginWindow).toHaveBeenCalledOnce();
    });
    it.each([
        new TypeError("fetch failed"),
        new DOMException("The operation timed out", "TimeoutError"),
    ])("recovers from a rejected poll: %s", async (error) => {
        const fetch = vi
            .spyOn(globalThis, "fetch")
            .mockResolvedValueOnce(Response.json({ id: "ticket-1" }))
            .mockRejectedValueOnce(error)
            .mockResolvedValueOnce(Response.json({ status: "completed", data: { token: "secret-key" } }))
            .mockResolvedValueOnce(Response.json({ user: { email: "user@example.com" } }));
        await runLogin(platform, "test");
        expect(fetch).toHaveBeenCalledTimes(4);
        expect(delay).toHaveBeenCalledExactlyOnceWith(1500);
        expect(saveCredentials).toHaveBeenCalledExactlyOnceWith("secret-key");
    });
    it.each([
        400, 401, 403, 404,
    ])("does not retry terminal HTTP %i", async (status) => {
        const fetch = vi
            .spyOn(globalThis, "fetch")
            .mockResolvedValueOnce(Response.json({ id: "ticket-1" }))
            .mockResolvedValueOnce(new Response(null, { status }));
        await expect(runLogin(platform, "test")).rejects.toThrow(`HTTP ${status}`);
        expect(fetch).toHaveBeenCalledTimes(2);
        expect(delay).not.toHaveBeenCalled();
        expect(saveCredentials).not.toHaveBeenCalled();
        expect(closeLoginWindow).not.toHaveBeenCalled();
    });
    it("recovers when reading a pending poll response fails", async () => {
        const interruptedResponse = new Response();
        vi.spyOn(interruptedResponse, "json").mockRejectedValueOnce(new TypeError("terminated"));
        vi.spyOn(globalThis, "fetch")
            .mockResolvedValueOnce(Response.json({ id: "ticket-1" }))
            .mockResolvedValueOnce(interruptedResponse)
            .mockResolvedValueOnce(Response.json({ status: "completed", data: { token: "secret-key" } }))
            .mockResolvedValueOnce(Response.json({ user: { email: "user@example.com" } }));
        await runLogin(platform, "test");
        expect(delay).toHaveBeenCalledExactlyOnceWith(1500);
        expect(saveCredentials).toHaveBeenCalledExactlyOnceWith("secret-key");
    });
    it("stops retrying at the ten-minute deadline", async () => {
        let now = 0;
        vi.spyOn(Date, "now").mockImplementation(() => now);
        const timeout = vi.spyOn(AbortSignal, "timeout");
        delay.mockImplementation(async (ms) => {
            now += ms;
        });
        const fetch = vi
            .spyOn(globalThis, "fetch")
            .mockResolvedValueOnce(Response.json({ id: "ticket-1", pollIntervalMs: 700 }))
            .mockRejectedValue(new TypeError("fetch failed"));
        await expect(runLogin(platform, "test")).rejects.toThrow("Login timed out");
        expect(now).toBe(600_000);
        expect(delay).toHaveBeenLastCalledWith(100);
        expect(timeout).toHaveBeenLastCalledWith(100);
        expect(fetch).toHaveBeenCalledTimes(859);
        expect(saveCredentials).not.toHaveBeenCalled();
        expect(closeLoginWindow).not.toHaveBeenCalled();
    });
    it("awaits login window cleanup before reporting completion", async () => {
        let finishCleanup;
        closeLoginWindow.mockImplementationOnce(() => new Promise((resolve) => {
            finishCleanup = resolve;
        }));
        vi.spyOn(globalThis, "fetch")
            .mockResolvedValueOnce(Response.json({ id: "ticket-1" }))
            .mockResolvedValueOnce(Response.json({ status: "completed", data: { token: "secret-key" } }))
            .mockResolvedValueOnce(Response.json({ user: { email: "user@example.com" } }));
        const onSuccess = vi.fn();
        const login = runLogin(platform, "test", { onSuccess });
        await vi.waitFor(() => expect(closeLoginWindow).toHaveBeenCalled());
        expect(saveCredentials).toHaveBeenCalledWith("secret-key");
        expect(onSuccess).not.toHaveBeenCalled();
        finishCleanup?.();
        await login;
        expect(onSuccess).toHaveBeenCalledOnce();
    });
    it("leaves the login window open when credential persistence fails", async () => {
        saveCredentials.mockImplementationOnce(() => {
            throw new Error("disk full");
        });
        vi.spyOn(globalThis, "fetch")
            .mockResolvedValueOnce(Response.json({ id: "ticket-1" }))
            .mockResolvedValueOnce(Response.json({ status: "completed", data: { token: "secret-key" } }));
        await expect(runLogin(platform, "test")).rejects.toThrow("disk full");
        expect(closeLoginWindow).not.toHaveBeenCalled();
    });
    it("keeps the manual sign-in link usable when a browser cannot launch", async () => {
        openBrowser.mockReturnValue({ launched: false });
        vi.spyOn(globalThis, "fetch")
            .mockResolvedValueOnce(Response.json({ id: "ticket-1" }))
            .mockResolvedValueOnce(Response.json({ status: "completed", data: { token: "secret-key" } }))
            .mockResolvedValueOnce(Response.json({ user: { email: "user@example.com" } }));
        await runLogin(platform, "test");
        expect(console.log).toHaveBeenCalledWith("Could not open a browser. Open the sign-in link above to continue.");
        expect(saveCredentials).toHaveBeenCalledWith("secret-key");
    });
});
